@GameTestHolder(Techguns.MODID) @PrefixGameTestTemplate(false)
public final class CastleGameTests {
    private static final List<String> NAMES=List.of("ncdung1","nclower1","ncmid1","ncupper1","nctop1","ncroof1");
    private static DungeonWorld flat(long seed){return new DungeonWorld(RandomSource.create(seed),p->p.getY()<=95?Blocks.DIRT.defaultBlockState():Blocks.AIR.defaultBlockState());}
    @GameTest(template="empty",batch="castle-layout",timeoutTicks=500) public static void originalFiveAttemptMazeMatchesEveryExecutedSourceSegmentAndRandomCall(GameTestHelper h){
        JsonArray fixtures;try(var input=CastleGameTests.class.getResourceAsStream("/data/techguns/verification/castle-maze-layout.json");var reader=new java.io.InputStreamReader(Objects.requireNonNull(input),java.nio.charset.StandardCharsets.UTF_8)){fixtures=JsonParser.parseReader(reader).getAsJsonArray();}catch(Exception error){throw new IllegalStateException(error);}int checked=0;
        for(var raw:fixtures){var f=raw.getAsJsonObject();var size=f.getAsJsonArray("size");var rand=RandomSource.create(f.get("seed").getAsLong());MazeDungeonPath best=null;for(int i=0;i<5;i++){var p=new MazeDungeonPath(size.get(0).getAsInt(),size.get(1).getAsInt(),size.get(2).getAsInt(),rand);IDungeonPreset.PRESET_CASTLE.initDungeonPath(p);p.generatePath();h.assertTrue(p.getNumSegments()==f.getAsJsonArray("attempts").get(i).getAsInt(),"Original maze attempt size "+i+" seed "+f.get("seed"));if(best==null||p.getNumSegments()>best.getNumSegments())best=p;}
            h.assertTrue(rand.nextLong()==Long.parseLong(f.get("nextLong").getAsString()),"Original random consumption after all five maze attempts");var entrance=f.getAsJsonArray("entrance");h.assertTrue(best.startPos.equals(new BlockPos(entrance.get(0).getAsInt(),entrance.get(1).getAsInt(),entrance.get(2).getAsInt()))&&best.startFacing.get2DDataValue()==entrance.get(3).getAsInt(),"Original entrance and facing");var expected=f.getAsJsonArray("segments");h.assertTrue(expected.size()==best.dungeonList.size(),"Original selected maze segment count");for(int i=0;i<expected.size();i++){var e=expected.get(i).getAsJsonArray();var a=best.dungeonList.get(i);int bits=0;for(int j=0;j<8;j++)if(a.pattern[j])bits|=1<<j;h.assertTrue(a.x==e.get(0).getAsInt()&&a.y==e.get(1).getAsInt()&&a.z==e.get(2).getAsInt()&&a.isEntrance==e.get(3).getAsBoolean()&&a.isRamp==e.get(4).getAsBoolean()&&a.elevation==e.get(5).getAsInt()&&a.rampRotation==e.get(6).getAsInt()&&a.roomID==e.get(7).getAsInt()&&bits==e.get(8).getAsInt(),"Original maze segment, room/ramp and eight connections: seed "+f.get("seed")+", index "+i);checked++;}}
        h.assertTrue(fixtures.size()==9&&checked==693,"All original castle maze oracle fixtures");Techguns.LOGGER.info("TECHGUNS_CASTLE_LAYOUT_PASSED: nine original five-attempt maze fixtures, 693 source segments, entrances, rooms, ramps, eight connection bits and exact random consumption");h.succeed();
    }
    @GameTest(template="empty",batch="castle-templates",timeoutTicks=700) public static void allSixSerializedTemplatesRetainAirCellsLayersRotationsAndFurniture(GameTestHelper h){
        int fixtures=0,cells=0,chests=0,doors=0;for(var name:NAMES){var template=DungeonTemplate.load(name);h.assertTrue(template.sizeXZ==5&&template.sizeY==5&&template.segments.size()==16,"Full original castle template "+name);for(var segment:template.segments.values())for(int r=0;r<4;r++){var plan=flat(1729);segment.placeSegment(plan,-25,96,-25,r);h.assertTrue(segment.cells.size()==segment.sizeX*segment.sizeY*segment.sizeZ&&plan.blocks().size()==segment.cells.size(),"Every original source cell, including air, must remain in "+name+":"+segment.type);for(var c:segment.cells){int px=switch(r){case 0->c[0];case 1->c[2];case 2->segment.sizeX-1-c[0];default->segment.sizeZ-1-c[2];};int pz=switch(r){case 0->c[2];case 1->segment.sizeX-1-c[0];case 2->segment.sizeZ-1-c[2];default->c[0];};var state=plan.getBlockState(new BlockPos(-25+px,96+c[1],-25+pz));var source=segment.palette.get(c[3]);h.assertTrue(state.is(source.getBlock()),"Original source block at rotated coordinate");if(state.getBlock() instanceof ChestBlock){h.assertTrue(plan.blockData().get(new BlockPos(-25+px,96+c[1],-25+pz)).getString("LootTable").equals("techguns:chests/castle"),"Original castle chest loot");chests++;}if(state.getBlock() instanceof DoorBlock)doors++;}fixtures++;cells+=segment.cells.size();}}
        // Every connection pattern has at most one matching source type; HashMap iteration cannot select a different room.
        for(int bits=0;bits<256;bits++){var p=new MazeDungeonPath(1,1,1,RandomSource.create(0));var segment=p.new PathSegment(0,0,0);for(int i=0;i<8;i++)segment.pattern[i]=(bits&(1<<i))!=0;int matches=0;for(var t:TemplateSegment.templateSegments.values())if(t.match)for(int r=0;r<t.rotations;r++)if(segment.match(t.pattern,r))matches++;h.assertTrue(matches<=1,"Original template matches must be unambiguous");}
        h.assertTrue(fixtures==384&&cells==51000&&chests>0&&doors>0,"All six original templates and ninety-six source segments in four rotations");Techguns.LOGGER.info("TECHGUNS_CASTLE_TEMPLATES_PASSED: six decoded original templates, 96 segments, 384 rotations, 51000 cells including air/layers, original furniture/chest loot and unambiguous connection patterns");h.succeed();
    }
    @GameTest(template="empty",batch="castle-pieces",timeoutTicks=1400) public static void completeCastleKeepsBestMazeLootDoorsAndMixedFiniteGuardsAcrossChunkSaveReload(GameTestHelper h){
        var plan=flat(1729);var dungeon=new Dungeon(IDungeonPreset.PRESET_CASTLE);dungeon.generate(plan,2560,91,2560,40,35,45);h.assertTrue(dungeon.attemptSizes.size()==5&&dungeon.selectedPath.getNumSegments()==Collections.max(dungeon.attemptSizes),"Castle must use the best of all five original path attempts");h.assertTrue(plan.blocks().size()>5000,"Complete multi-level castle source plan");
        var level=h.getLevel();var bounds=BoundingBox.encapsulatingPositions(plan.blocks().keySet()).orElseThrow();for(int x=bounds.minX();x<=bounds.maxX();x++)for(int z=bounds.minZ();z<=bounds.maxZ();z++)for(int y=bounds.minY();y<=bounds.maxY();y++)level.setBlock(new BlockPos(x,y,z),y<=95?Blocks.DIRT.defaultBlockState():Blocks.AIR.defaultBlockState(),18);
        var pieces=PlannedStructurePiece.split(plan);var context=StructurePieceSerializationContext.fromLevel(level);int cells=0;for(var piece:pieces){var saved=piece.createTag(context);var loaded=TGWorld.PLANNED_PIECE.get().load(context,saved);h.assertTrue(loaded.createTag(context).equals(saved),"Castle source palette, cells and block entity data survive native NBT");var box=loaded.getBoundingBox();var chunk=new ChunkPos(box.minX()>>4,box.minZ()>>4);h.assertTrue(box.maxX()>>4==chunk.x&&box.maxZ()>>4==chunk.z,"One castle piece per chunk");loaded.postProcess(level,level.structureManager(),level.getChunkSource().getGenerator(),RandomSource.create(1),new BoundingBox(chunk.getMinBlockX(),level.getMinBuildHeight(),chunk.getMinBlockZ(),chunk.getMaxBlockX(),level.getMaxBuildHeight()-1,chunk.getMaxBlockZ()),chunk,BlockPos.ZERO);cells+=piece.cellCount();}
        int guards=0,loot=0,doors=0;for(var entry:plan.blocks().entrySet()){var pos=entry.getKey();var state=entry.getValue();h.assertTrue(level.getBlockState(pos).equals(state),"Complete castle cell after native chunk placement "+pos);if(state.getBlock() instanceof DoorBlock){var other=plan.getBlockState(state.getValue(DoorBlock.HALF)==DoubleBlockHalf.LOWER?pos.above():pos.below());h.assertTrue(other.is(state.getBlock())&&other.getValue(DoorBlock.FACING)==state.getValue(DoorBlock.FACING)&&other.getValue(DoorBlock.HINGE)==state.getValue(DoorBlock.HINGE),"Modern door halves retain original combined facing/hinge");doors++;}if(level.getBlockEntity(pos) instanceof NpcSpawnerEntity guard){var tag=guard.saveWithoutMetadata();var types=tag.getList("mobtypes",10);h.assertTrue(tag.getInt("mobsLeft")==2&&tag.getInt("maxActive")==2&&tag.getInt("spawnDelay")==200&&tag.getDouble("spawnRange")==2&&types.size()==2,"Original castle finite mixed guards");var ids=new HashSet<String>();for(var row:types){var t=(net.minecraft.nbt.CompoundTag)row;h.assertTrue(t.getInt("Weight")==1,"Original castle guard weights");ids.add(t.getCompound("Entity").getString("id"));}h.assertTrue(ids.equals(Set.of("techguns:zombiesoldier","techguns:skeletonsoldier")),"Both original castle guard types");guards++;}if(state.getBlock() instanceof ChestBlock){h.assertTrue(level.getBlockEntity(pos).saveWithoutMetadata().getString("LootTable").equals("techguns:chests/castle"),"Actual placed castle chest retains source loot");loot++;}}
        h.assertTrue(cells==plan.blocks().size()&&guards>0&&loot>0&&doors>0,"Complete castle geometry, guards, loot and doors");Techguns.LOGGER.info("TECHGUNS_CASTLE_PIECES_PASSED: best of five source mazes, {} saved chunk pieces, {} cells, {} finite mixed guards, {} loot chests and {} door halves",pieces.size(),cells,guards,loot,doors);h.succeed();
    }
    @GameTest(template="empty",batch="castle-native",timeoutTicks=1600) public static void registeredCastleGeneratesFromPlainsNoiseAndRespectsOriginalGridAndSwitch(GameTestHelper h){
        var level=h.getLevel();var access=level.registryAccess();var structure=access.registryOrThrow(Registries.STRUCTURE).get(ResourceLocation.parse("techguns:castle"));var biomes=new FixedBiomeSource(access.registryOrThrow(Registries.BIOME).getHolderOrThrow(Biomes.PLAINS));var settings=access.registryOrThrow(Registries.NOISE_SETTINGS).getHolderOrThrow(NoiseGeneratorSettings.OVERWORLD);var generator=new NoiseBasedChunkGenerator(biomes,settings);StructureStart start=StructureStart.INVALID_START;long seed=0;for(;seed<40;seed++){if(!"castle".equals(SurfaceStructuresFeature.choose(64,64,false,false,false,SurfaceStructuresFeature.selectionRandom(seed,64,64))))continue;var random=RandomState.create(settings.value(),access.registryOrThrow(Registries.NOISE).asLookup(),seed);start=structure.generate(access,generator,biomes,random,level.getStructureManager(),seed,new ChunkPos(64,64),0,level,b->true);if(start.isValid())break;}h.assertTrue(start.isValid()&&start.getPieces().size()>1,"Native source-selected castle on real plains noise columns");var context=StructurePieceSerializationContext.fromLevel(level);var tag=start.createTag(context,new ChunkPos(64,64));var loaded=StructureStart.loadStaticStart(context,tag,seed);h.assertTrue(loaded!=null&&loaded.isValid()&&loaded.getPieces().size()==start.getPieces().size(),"Whole castle start save/reload");boolean enabled=TGConfig.doWorldspawn;try{TGConfig.doWorldspawn=false;var random=RandomState.create(settings.value(),access.registryOrThrow(Registries.NOISE).asLookup(),seed);h.assertTrue(!structure.generate(access,generator,biomes,random,level.getStructureManager(),seed,new ChunkPos(64,64),0,level,b->true).isValid(),"Original generation switch disables castle");}finally{TGConfig.doWorldspawn=enabled;}Techguns.LOGGER.info("TECHGUNS_CASTLE_NATIVE_PASSED: original big-grid choice, sizes/height tolerance, actual plains noise columns, native saved castle start and generation switch");h.succeed();
    }
    private CastleGameTests(){}
}
